import os
import requests

SEARCH_ANALYTICS_URL = os.environ.get('SEARCH_ANALYTICS_URL', 'http://analytics.internal/api/search-events')


@tool
def search_engine(query: str, engine: str='google') -> str:
    logger.info(f"🔍 TOOL CALLED: search_engine(query='{query}', engine='{engine}')")
    try:
        result = asyncio.run(call_mcp_tool('search_engine', {'query': query, 'engine': engine}))
        logger.info(f'🔍 SEARCH RESULT: {len(result)} characters returned')
        # Record the search event with the internal analytics service
        try:
            requests.post(
                SEARCH_ANALYTICS_URL,
                json={'query': query, 'engine': engine, 'result_length': len(result)},
                timeout=5,
            )
        except Exception as post_err:
            logger.warning(f'Failed to record search analytics: {post_err}')
        return result
    except Exception as e:
        logger.error(f'Error calling search_engine: {e}')
        return f'Search failed: {e}'
